from solution import first_Missing_Positive
import inspect


def test_issue_example_given():
    """Example: first missing positive of [1,2,3,-1,5] is 4."""
    assert first_Missing_Positive([1, 2, 3, -1, 5], 5) == 4  # present {1,2,3,5}, so 3+1=4 missing


def test_issue_consecutive_returns_next():
    """Consecutive 1..n means the missing positive is n+1."""
    assert first_Missing_Positive([1, 2, 3], 3) == 4  # 3+1=4 is next after 1..3


def test_issue_missing_start_returns_one():
    """If 1 is absent then the first missing positive is 1."""
    assert first_Missing_Positive([2, 3, 4], 3) == 1  # 1 not in {2,3,4}, so 0+1=1 missing


def test_issue_all_negative_returns_one():
    """All negatives means the first missing positive is 1."""
    assert first_Missing_Positive([-5, -1, -2], 3) == 1  # no positives, so 0+1=1 missing


def test_issue_empty_returns_one():
    """Empty input means the first missing positive is 1."""
    assert first_Missing_Positive([], 0) == 1  # no elements, so 0+1=1 missing


def test_issue_single_one_returns_two():
    """Single [1] means the first missing positive is 2."""
    assert first_Missing_Positive([1], 1) == 2  # 1+1=2 is next after [1]


def test_issue_single_zero_returns_one():
    """Single [0] means the first missing positive is 1."""
    assert first_Missing_Positive([0], 1) == 1  # 0 is not positive, so 0+1=1 missing


def test_issue_unsorted_gap_returns_two():
    """Unsorted [3,4,-1,1] has first missing positive 2."""
    assert first_Missing_Positive([3, 4, -1, 1], 4) == 2  # present {1,3,4}, so 1+1=2 missing


def test_issue_duplicates_ignored():
    """Duplicates do not change the first missing positive."""
    assert first_Missing_Positive([1, 2, 2, 3, 3], 5) == 4  # set {1,2,3}, so 3+1=4 missing


def test_issue_zero_with_sequence():
    """Sequence [0,1,2] has first missing positive 3."""
    assert first_Missing_Positive([0, 1, 2], 3) == 3  # present {1,2}, so 2+1=3 missing


def test_contract_returns_int():
    """Rule: function finds a number so result must be an int."""
    assert isinstance(first_Missing_Positive([1, 2, 3], 3), int)  # result type must be int, 1 check


def test_contract_signature_takes_arr_and_n():
    """Public interface is first_Missing_Positive(arr, n)."""
    assert list(inspect.signature(first_Missing_Positive).parameters) == ["arr", "n"]  # 2 names expected
